INSERT INTO `wpis_wfissues` VALUES (19821,1604220459,1604220459,'new','wfPluginAbandoned',50,'72b0a014e93073b1ced0c644db72c989','72b0a014e93073b1ced0c644db72c989','The Plugin \"Simple Twitter Tweets\" appears to be abandoned (updated 2016-03-24, tested to WP 4.4.24).','It was last updated 4 years 7 months ago and tested up to WordPress 4.4.24. Plugins can be removed from wordpress.org for various reasons. This can include benign issues like a plugin author discontinuing development or moving the plugin distribution to their own site, but some might also be due to security issues. In any case, future updates may or may not be available, so it is worth investigating the cause and deciding whether to temporarily or permanently replace or remove the plugin. <a href=\"https://www.wordfence.com/help/?query=scan-result-plugin-abandoned\" target=\"_blank\" rel=\"noopener noreferrer\">Get more information.</a>','a:19:{s:4:\"name\";s:21:\"Simple Twitter Tweets\";s:4:\"slug\";s:21:\"simple-twitter-tweets\";s:7:\"version\";s:3:\"4.4\";s:6:\"author\";s:67:\"<a href=\"http://www.planet-interactive.co.uk/\">Ashley Sheinwald</a>\";s:14:\"author_profile\";s:49:\"https://profiles.wordpress.org/planet-interactive\";s:8:\"requires\";s:3:\"3.0\";s:6:\"tested\";s:6:\"4.4.24\";s:12:\"requires_php\";b:0;s:13:\"compatibility\";a:0:{}s:11:\"num_ratings\";i:15;s:15:\"support_threads\";i:1;s:24:\"support_threads_resolved\";i:0;s:12:\"last_updated\";s:21:\"2016-03-24 2:12pm GMT\";s:8:\"homepage\";s:57:\"http://www.planet-interactive.co.uk/simple-twitter-tweets\";s:13:\"download_link\";s:68:\"https://downloads.wordpress.org/plugin/simple-twitter-tweets.4.4.zip\";s:11:\"dateUpdated\";s:10:\"2016-03-24\";s:9:\"abandoned\";b:1;s:10:\"vulnerable\";b:0;s:5:\"wpURL\";s:51:\"https://wordpress.org/plugins/simple-twitter-tweets\";}'),(19819,1604219984,1604219984,'new','knownfile',50,'1c699ce0df5c854b50a69d6493dc13b4','9dfa6fd23429d8695f751409c62763e3','Modified theme file: wp-content/themes/twentytwenty/