INSERT INTO `wpis_wfpendingissues` VALUES (1,1604219976,1604219976,'new','knownfile',50,'1c699ce0df5c854b50a69d6493dc13b4','9dfa6fd23429d8695f751409c62763e3','Modified theme file: wp-content/themes/twentytwenty/classes/class-twentytwenty-customize.php','This file belongs to theme \"Twenty Twenty\" version \"1.5\" and has been modified from the original distribution. It is common for site owners to modify their theme files, so if you have modified this file yourself you can safely ignore this warning. <a href=\"https://www.wordfence.com/help/?query=scan-result-modified-theme\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>','a:9:{s:4:\"file\";s:71:\"wp-content/themes/twentytwenty/classes/class-twentytwenty-customize.php\";s:5:\"cType\";s:5:\"theme\";s:7:\"canDiff\";b:1;s:6:\"canFix\";b:1;s:9:\"canDelete\";b:0;s:5:\"cName\";s:13:\"Twenty Twenty\";s:8:\"cVersion\";s:3:\"1.5\";s:4:\"cKey\";s:12:\"twentytwenty\";s:10:\"haveIssues\";s:6:\"themes\";}'),(2,1604219976,1604219976,'new','knownfile',50,'1fc5c5a5abcea786374b73834830ade0','2b2ec0c9d4268ebf5ae07f9e7aefd2f8','Modified theme file: wp-content/themes/twentytwenty/package-lock.json','This file belongs to theme \"Twenty Twenty\" version \"1.5\" and has been modified from the original distribution. It is common for site owners to modify their theme files, so if you have modified this file yourself you can safely ignore this warning. <a href=\"https://www.wordfence.com/help/?query=scan-result-modified-theme\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>','a:9:{s:4:\"file\";s:48:\"wp-content/themes/twentytwenty/package-lock.json\";s:5:\"cType\";s:5:\"theme\";s:7:\"canDiff\";b:1;s:6:\"canFix\";b:1;s:9:\"canDelete\";b:0;s:5:\"cName\";s:13:\"Twenty Twenty\";s:8:\"cVersion\";s:3:\"1.5\";s:4:\"cKey\";s:12:\"twentytwenty\";s:10:\"haveIssues\";s:6:\"themes\";}');
